function irPathProfile(raceId=state?.character?.race,bgId=state?.character?.background){const b=BACKGROUNDS[bgId]||BACKGROUNDS.village;return IR_SPECIAL_BACKGROUNDS[bgId]||b}
function irChooseStartIndex(world,raceId,bgId,circ){const sites=world.region.sites;const rng=irRng(`${world.seed}|${raceId}|${bgId}|${circ}|start-v3`);const bg=BACKGROUNDS[bgId]||{};let candidates=sites;
 if(circ==='settlement')candidates=sites.filter(s=>s.type==='settlement');
 else if(circ==='remote')candidates=sites.filter(s=>['remote','hamlet'].includes(s.settlementType));
 else if(circ==='roadside')candidates=sites.filter(s=>s.type!=='settlement'&&s.routes.some(rt=>{const q=sites.find(x=>x.id===rt.to);return q?.type==='settlement'}));
 else if(circ==='wilderness')candidates=sites.filter(s=>s.type!=='settlement'&&s.risk>=20&&s.risk<=48);
 const prefer={human:['plains','woodland','river'],dwarf:['mountain','forest','woodland'],elf:['forest','river','mountain'],beastkin:['forest','plains','snow','woodland'],orc:['plains','mountain','woodland'],goblin:['woodland','swamp','plains'],demonkin:['swamp','mountain','snow','forest'],slimefolk:['swamp','river','coast']}[raceId]||['woodland'];
 if(circ==='settlement')candidates=candidates.filter(s=>['human','dwarf','elf','beastkin','orc','goblin','demonkin','slimefolk'].includes(raceId));
 if(!candidates.length)candidates=sites.filter(s=>s.type!=='settlement');
 const scores=candidates.map(s=>({s,weight:1+(prefer.includes(s.biomeId)?1.6:0)+(bg.defaultStart===circ&&s.risk<25?.25:0)+(raceId==='dwarf'&&['town','city'].includes(s.settlementType)?1.4:0)+(raceId==='demonkin'&&s.settlementType==='remote'?1.5:0)+(raceId==='slimefolk'&&s.settlementType==='remote'?1:0)}));const total=scores.reduce((sum,x)=>sum+x.weight,0);let pick=rng()*total;for(const x of scores){pick-=x.weight;if(pick<=0)return x.s.index}return scores[scores.length-1]?.s.index??24;
}
function irResetWorldStart(world,index,circ,raceId,bgId){const sites=world.region.sites;const start=sites.find(s=>s.index===index)||sites[24];for(const s of sites){s.discovered=false;s.visits=0;s.changes=s.changes||{};s.changes.temporaryCamp=false;delete s.changes.lastVisited;}start.discovered=true;start.visits=1;start.changes.lastVisited={year:102,month:1,day:1};if(circ==='roadside')start.changes.temporaryCamp=true;world.siteId=start.id;world.startCircumstance=circ;world.startRace=raceId;world.startBackground=bgId;world.visited=[start.id];world.known=[start.id,...start.routes.map(rt=>rt.to)];const j=world.journal||{rumors:[]};j.knownLocations=world.known.slice();j.visitedLocations=[start.id];const bg=BACKGROUNDS[bgId]||BACKGROUNDS.village;const raceName=RACES[raceId]?.name||'Traveler';j.discoveries=[{id:`start-v3-${start.id}`,title:`${bg.name}: ${start.name}`,detail:`${raceName} · ${bg.opening||IR_RACE_START_STORIES[raceId]?.[circ]||'A new life begins on the frontier.'}`,siteId:start.id,date:'START OF JOURNEY'}];j.rumors=Array.isArray(j.rumors)?j.rumors:[];world.journal=j;world.travelCount=0;return start}
function irBackgroundCards(){const ids=[...Object.keys(IR_SPECIAL_BACKGROUNDS).filter(id=>IR_SPECIAL_BACKGROUNDS[id].race===createRace),...IR_COMMON_BACKGROUNDS];return ids.map(id=>{const b=BACKGROUNDS[id];return `<button class="background-card ${id===createBackground?'selected':''}" data-background="${id}"><span class="bg-icon">${b.icon}</span><strong>${esc(b.name)}</strong><p>${esc(b.desc)}</p><small>◈ ${b.coins} coins · ${esc(b.path||'Flexible path')}</small></button>`}).join('')}
renderTitle = function(){let html=irV02RenderTitle();const p=html.indexOf('<div class="background-grid">');if(p>=0){const end=html.indexOf('</div>',p)+6;html=html.slice(0,p)+'<div class="background-grid ir-background-grid">'+irBackgroundCards()+'</div>'+html.slice(end);const next=html.indexOf('<section class="panel creator-panel"><div class="panel-heading"><div><div class="eyebrow">STEP 3 · YOUR WORLD');const step2=html.lastIndexOf('</section>',next);if(step2>0){const prof=irPathProfile(createRace,createBackground),story=prof.opening||IR_RACE_START_STORIES[createRace]?.[createStart]||'Your choices shape the way this life begins.';const insert=`<div class="ir-path-preview"><div class="tiny-label">YOUR LIFE PATH · ${esc(RACES[createRace].name)}</div><h3>${esc(prof.name||'Flexible Background')}</h3><p>${esc(story)}</p><small>Starting scene: ${esc(IR_STARTS[createStart]?.name||'Village or town')} · This race and background influence your opening location, work, events, and combat bonuses.</small></div>`;html=html.slice(0,step2)+insert+html.slice(step2)}}html=html.replace(/VERSION 0\.2/g,'VERSION 0.4').replace(/WORLD V2/g,'WORLD V3').replace('old-age death is not simulated in v0.1.','old-age death is not simulated yet.');return html}
makeInitial = function(name,raceId,bgId){const cRace=RACES[raceId]?raceId:'human',bgKey=BACKGROUNDS[bgId]?bgId:(IR_DEFAULT_BACKGROUND[cRace]||'village');const prof=BACKGROUNDS[bgKey];/* v0.4: the player's explicitly selected starting circumstance is authoritative. */const s=irV02MakeInitial(name,cRace,bgKey);s.version=3;const startIndex=irChooseStartIndex(s.world,cRace,bgKey,createStart);const start=irResetWorldStart(s.world,startIndex,createStart,cRace,bgKey);const c=s.character;c.background=bgKey;c.lifePath=prof.path||'Independent';c.openingStory=`${prof.opening||IR_RACE_START_STORIES[cRace]?.[createStart]||'A new life begins.'} ${IR_RACE_START_STORIES[cRace]?.[createStart]||''}`.trim();c.pathProgress={offersTaken:0,contractsCompleted:0,contactReputation:{locals:0,shadow:0,craft:0,arcane:0,wilds:0},flags:[]};c.combatStats={wins:0,defeats:0,escapes:0,monstersDefeated:0,totalExperience:0};c.injuries=[];c.relationships=c.relationships||{};c.equipment={weapon:c.inventory.axe?'axe':c.inventory.staff?'staff':c.inventory.dagger?'dagger':null,armor:c.inventory.leather_armor?'leather_armor':null,offhand:c.inventory.shield?'shield':null};c.reputation=clamp(c.reputation+(Number(prof.reputation)||0),-100,100);c.contacts=[];if(cRace==='demonkin')c.contacts.push({id:'masked_intermediary',name:'The Masked Intermediary',kind:'occult',trust:0});if(cRace==='goblin')c.contacts.push({id:'scrap_vendor',name:'Nix Copperthumb',kind:'salvage',trust:1});if(cRace==='dwarf')c.contacts.push({id:'forge_contact',name:'Borin Anvilhand',kind:'craft',trust:1});s.world.dungeon=null;s.combat=null;s.warning=null;s.hunt=null;s.pathEventHistory=[];s.feed[0].detail=`${c.name}, a ${RACES[cRace].name} with the ${prof.name} background, awakens at ${start.name} in ${s.world.region.name}. ${c.openingStory} Seed ${s.world.seed} created a connected frontier. The chosen race and background shape this starting point and early opportunities.`;s.feed[0].date='START OF JOURNEY';return s}

function irIsSpecialJob(j){return !!j.pathRace}
function irJobMeetsRequirements(j,c=state.character){if(j.pathRace&&j.pathRace!==c.race)return false;if(j.pathBackgrounds?.length&&!j.pathBackgrounds.includes(c.background)&&!site()?.services?.includes(j.service))return false;for(const [skill,level] of Object.entries(j.minSkills||{}))if((c.skills[skill]?.level||1)<level)return false;for(const [stat,value] of Object.entries(j.minAttrs||{}))if((c.attrs[stat]||0)<value)return false;if(j.service&&!site()?.services?.includes(j.service)&&!(j.pathBackgrounds||[]).includes(c.background))return false;return true}
function irAvailableJobs(){if(!state?.character)return [];const s=site(),c=state.character;return JOBS.filter(j=>{if(j.pathRace){if(j.pathRace!==c.race)return false;return irJobMeetsRequirements(j,c)}return !!s?.services?.includes('work-board')&&irJobMeetsRequirements(j,c)}).sort((a,b)=>Number(!!b.pathRace)-Number(!!a.pathRace))}
jobPanel = function(){const c=state.character,j=JOBS.find(x=>x.id===c.job);if(j){return `<div class="panel panel-pad"><div class="panel-heading"><div><h3>Your work</h3><p>One shift takes five days. Work can carry consequences beyond coin.</p></div><span class="tag gold">EMPLOYED</span></div><div class="job-row"><div class="row-icon">${j.icon}</div><div class="row-main"><strong>${esc(j.name)}</strong><p>${esc(j.desc)}</p><p>${j.pathRace?`Life-path specialty · ${esc(j.specialty||'Race-specific')}`:'Common employment'}</p></div><div class="row-side"><b>+${j.pay} ◈</b><button class="button small" data-action="work">Work shift</button></div></div><div style="margin-top:12px"><button class="button subtle small" data-action="quit-job">Leave this job</button></div></div>`}
 const jobs=irAvailableJobs();const current=site();return `<div class="panel panel-pad"><div class="panel-heading"><div><h3>Work & life paths</h3><p>Jobs depend on race, background, skill, and local services.</p></div><span class="tag">${jobs.length} OPEN</span></div>${jobs.length?jobs.map(j=>`<div class="job-row"><div class="row-icon">${j.icon}</div><div class="row-main"><strong>${esc(j.name)} ${j.pathRace?'<span class="tag purple">SPECIALTY</span>':''}</strong><p>${esc(j.desc)}</p><p>Entry: ${esc(j.req)}${j.pathRace?' · '+esc(RACES[j.pathRace].name):''}</p></div><div class="row-side"><b>+${j.pay} ◈</b><button class="button small" data-action="apply-job" data-job="${j.id}">Apply</button></div></div>`).join(''):`<div class="empty">There are no jobs you qualify for at ${esc(current.name)}. Visit a settlement with a work board, guild, market, library, or caravan service. Your background may reveal a special contract even when the local board is quiet.</div>`}<div class="ir-opportunity-box"><div><strong>${RACES[c.race].icon} A path-specific opportunity</strong><p>Look for a contract, clue, or contact shaped by your race and background. Some offers are risky; refusing is always allowed.</p></div><button class="button primary" data-action="seek-opportunity">Seek opportunity</button></div><div class="ir-career-footnote">${esc(RACES[c.race].name)} path: ${esc(c.lifePath||'Independent')}. Complete contracts to build contacts and open more specialized work.</div></div>`}
findWork = function(id){const c=state?.character,j=JOBS.find(x=>x.id===id);if(!c||!j)return;if(c.job){toast('You already have a job. Leave it before taking another.');return}if(!irJobMeetsRequirements(j,c)){toast(`You do not currently qualify for ${j.name}. Check the skill, race, background, and location requirements.`);return}c.job=id;c.mood=clamp(c.mood+3,0,100);c.pathProgress=c.pathProgress||{offersTaken:0,contractsCompleted:0,contactReputation:{},flags:[]};if(j.pathRace){c.pathProgress.offersTaken++;if(!c.pathProgress.flags.includes(`job-${id}`))c.pathProgress.flags.push(`job-${id}`)}addFeed(j.icon,'New work: '+j.name,`${j.desc} Your shift takes five days and pays ${coins(j.pay)}.`, 'milestone');modal=null;persist();render();toast(`Hired as ${j.name}.`)}
doWork = function(){const c=state?.character;if(!c)return;if(!c.job){modal={kind:'jobs'};render();return}const j=JOBS.find(x=>x.id===c.job);if(!j){c.job=null;persist();render();return}if(!actionCost(20))return;c.energy=clamp(c.energy-20,0,c.maxEnergy);c.mood=clamp(c.mood+2,0,100);dayPass(5,'work');let pay=Math.round(j.pay*(race().mods.work||1))+Math.floor(Math.max(0,(c.skills.Trade?.level||1)-1)/3);let result='You completed your shift and were paid.';if(j.id==='demonkin_cursewright'||j.id==='demonkin_shadow'){const occult=(c.skills.Magic?.level||1)+(c.skills.Lore?.level||1)+Math.floor((c.attrs.Wisdom||10)/5);const success=Math.random()<clamp(.58+(occult-4)*.035,.25,.92);if(success){pay+=Math.floor(5+Math.random()*12);c.pathProgress.contactReputation.shadow=clamp((c.pathProgress.contactReputation.shadow||0)+2,-10,20);c.reputation=clamp(c.reputation-1,-100,100);result='The discreet assignment succeeded. Your contact paid a premium, but rumors may make ordinary merchants more cautious.'}else{pay=Math.floor(pay*.45);c.reputation=clamp(c.reputation-2,-100,100);c.pathProgress.contactReputation.shadow=clamp((c.pathProgress.contactReputation.shadow||0)-1,-10,20);result='The assignment went poorly and word spread. You received only part of the fee and local trust fell.'}}else if(j.id==='orc_guard'){if(Math.random()<.2){pay+=8;gainSkill('Combat',8);result='The road stayed quiet, but your alertness earned a bonus and a little combat practice.'}else result='The caravan reached the next safe stop. Your employer paid for the protection and calm presence.'}else if(j.id==='goblin_scrapwright'){const salvage=Math.random()<.65?'scrap':(Math.random()<.5?'ore':'dagger');c.inventory[salvage]=(c.inventory[salvage]||0)+1;result=`Your eye for salvage found a reusable ${ITEMS[salvage].name.toLowerCase()} in the workshop returns.`}else if(j.id==='human_mediator'||j.id==='human_envoy'){const smooth=(c.skills.Social?.level||1)+(c.skills.Trade?.level||1)+(c.attrs.Charisma||10)/6;if(smooth>=5){pay+=8;c.reputation=clamp(c.reputation+1,-100,100);c.pathProgress.contactReputation.locals=clamp((c.pathProgress.contactReputation.locals||0)+1,-10,20);result='You settled a difficult disagreement without escalating it. Your employer added a negotiation bonus and local trust improved.'}else{result='You carried the agreement through, though neither side would budge much. The base fee was paid and you practiced negotiation.'}}else if(j.id==='dwarf_forge'){const material=Math.random()<.62?'scrap':'ore';c.inventory[material]=(c.inventory[material]||0)+1;if((c.skills.Crafting?.level||1)>=2)pay+=6;result=`Your careful work in the forge reclaimed ${ITEMS[material].name.toLowerCase()} from a damaged tool. The smith noted your precision.`}else if(j.id==='dwarf_delver'){const material=Math.random()<.7?'ore':'scrap';c.inventory[material]=(c.inventory[material]||0)+1;gainSkill('Survival',10);result=`You marked a safe route and identified a seam of ${ITEMS[material].name.toLowerCase()}. The crew avoided a costly mistake.`}else if(j.id==='elf_arcanist'){const material=Math.random()<.55?'charm':'curse_shard';c.inventory[material]=(c.inventory[material]||0)+1;gainSkill('Magic',10);result=`Your research uncovered a useful ${ITEMS[material].name.toLowerCase()} and helped document an unfamiliar magical pattern.`}else if(j.id==='elf_groveward'){c.inventory.herb=(c.inventory.herb||0)+2;if(Math.random()<.28)c.inventory.potion=(c.inventory.potion||0)+1;gainSkill('Survival',10);result='You tended the greenway and gathered medicinal plants. A careful preparation may also have yielded a minor potion.'}else if(j.id==='beastkin_tracker'){const material=Math.random()<.55?'wolf_fang':'herb';c.inventory[material]=(c.inventory[material]||0)+1;gainSkill('Survival',12);result=`You followed the trail safely and recovered ${ITEMS[material].name.toLowerCase()} as proof of your findings.`}else if(j.id==='beastkin_warden'){const local=site();if(local)local.risk=Math.max(1,(local.risk||10)-2);gainSkill('Survival',10);pay+=4;result='You redirected a dangerous animal away from the path. The route is slightly safer and your employer paid a field bonus.'}else if(j.id==='orc_fighter'){gainSkill('Combat',20);if(Math.random()<.35){pay+=12;result='You won your bout cleanly and took a prize purse on top of the base fee.'}else{result='You held your own in the pit and left with valuable combat experience.'}}else if(j.id==='goblin_trapper'){const material=Math.random()<.45?'smoke_bomb':'scrap';c.inventory[material]=(c.inventory[material]||0)+1;gainSkill('Crafting',10);result=`Your improvised trap work produced ${ITEMS[material].name.toLowerCase()} for the next job.`}else if(j.id==='slimefolk_alchemist'){const material=Math.random()<.65?'potion':'charm';c.inventory[material]=(c.inventory[material]||0)+1;gainSkill('Magic',8);result=`Your sample remained stable and produced ${ITEMS[material].name.toLowerCase()} for the laboratory.`}else if(j.id==='slimefolk_collector'){const material=['herb','ore','scrap'][Math.floor(Math.random()*3)];c.inventory[material]=(c.inventory[material]||0)+1;gainSkill('Crafting',10);result=`You separated a compatible ${ITEMS[material].name.toLowerCase()} from mixed residue without harming yourself.`}c.coin+=pay;c.jobShifts=(c.jobShifts||0)+1;gainSkill(j.skill||'Trade',j.pathRace?18:15);if(j.pathRace){c.pathProgress=c.pathProgress||{offersTaken:0,contractsCompleted:0,contactReputation:{},flags:[]};c.pathProgress.contractsCompleted=(c.pathProgress.contractsCompleted||0)+1;const faction=j.shadow?'shadow':(['dwarf_forge','dwarf_delver'].includes(j.id)?'craft':['elf_arcanist','elf_groveward','slimefolk_alchemist'].includes(j.id)?'arcane':['beastkin_tracker','beastkin_warden'].includes(j.id)?'wilds':'locals');c.pathProgress.contactReputation[faction]=clamp((c.pathProgress.contactReputation[faction]||0)+1,-10,20)}addFeed(j.icon,`Shift completed: ${j.name}`,`${result} Earned ${coins(pay)} and practiced ${j.skill}.`, 'activity');persist();render();toast(`Shift complete. +${coins(pay)}.`)}
function irPathEventForCharacter(){const c=state.character;const event=IR_PATH_EVENTS[c.race]||'path_mediation';if(c.background==='demonkin_exile')return 'path_contract';return event}
function irSeekOpportunity(){if(state.combat?.active){toast('Finish the encounter before looking for a new contract.');return}const c=state.character;const event=irPathEventForCharacter();if(state.pendingEvent){toast('Resolve the current choice first. The world already has something awaiting you.');return}state.pathEventHistory=Array.isArray(state.pathEventHistory)?state.pathEventHistory:[];triggerEvent(event);c.pathProgress=c.pathProgress||{offersTaken:0,contractsCompleted:0,contactReputation:{},flags:[]};c.pathProgress.offersTaken=(c.pathProgress.offersTaken||0)+1;addFeed(RACES[c.race].icon,'A life-path lead',`A new opportunity connected to your ${irPathProfile(c.race,c.background).name} background has surfaced.`);persist();render();toast('A race- and background-aware opportunity is waiting for your decision.')}
function irFinishPathEvent(id,choice){const c=state.character;const e=EVENTS[id];if(!e||!id.startsWith('path_'))return false;let msg='',ico='✦';const energyCost=n=>{c.energy=clamp(c.energy-n,0,c.maxEnergy)};switch(`${id}:${choice}`){
 case'path_mediation:mediate':{dayPass(1,'mediation');energyCost(5);const skill=(c.skills.Social?.level||1)+(c.attrs.Charisma||10)/5;const pay=skill>=5?24:12;c.coin+=pay;c.reputation=clamp(c.reputation+(skill>=5?2:1),-100,100);gainSkill('Social',20);msg=`You heard both traders and proposed terms they could accept. Earned ${coins(pay)} and improved your local standing.`;break}
 case'path_mediation:sideA':dayPass(1,'mediation');energyCost(4);c.coin+=14;c.reputation=clamp(c.reputation-1,-100,100);gainSkill('Social',8);msg='The first trader paid you for support. The other trader is displeased, and the dispute remains unresolved.';break;
 case'path_forge:repair':{dayPass(2,'forge commission');energyCost(12);const pay=24+Math.floor((c.skills.Crafting?.level||1)*3);c.coin+=pay;c.inventory.scrap=Math.max(0,c.inventory.scrap||0)+1;gainSkill('Crafting',28);msg=`You repaired the tool set and earned ${coins(pay)} plus a useful scrap offcut.`;break}
 case'path_forge:negotiate':{const success=(c.skills.Trade?.level||1)+(c.attrs.Charisma||10)/5>=4;dayPass(2,'negotiated forge work');energyCost(10);const pay=success?38:18;c.coin+=pay;gainSkill('Crafting',20);gainSkill('Trade',8);msg=success?`You justified a higher fee and earned ${coins(pay)}.`:`Your bargaining fell flat, but you still earned ${coins(pay)} for doing the work.`;break}
 case'path_runes:study':dayPass(2,'rune study');energyCost(8);gainSkill('Lore',25);gainSkill('Magic',23);if(Math.random()<.6)c.inventory.curse_shard=(c.inventory.curse_shard||0)+1;else c.inventory.charm=(c.inventory.charm||0)+1;msg='You recorded the rune sequence. Lore and Magic improved, and the study yielded a small magical find.';break;
 case'path_runes:sell':dayPass(1,'scholar lead');energyCost(3);c.coin+=18;gainSkill('Lore',10);msg='You made careful notes and sold the lead to a scholar. The site remains marked in your journal.';break;
 case'path_tracks:pursue':{dayPass(1,'tracking');energyCost(9);const enemy=irPick(irRng(`${state.world.seed}-${site().id}-${c.daysLived}-hunt-path`),irBiomeEncounterIds(site())).replace('direwolf','wolf');state.hunt={enemyId:enemy,quality:clamp((c.skills.Survival?.level||1)+(c.attrs.Perception||10)/3,1,20),siteId:site().id,origin:'lifePath',startedAt:dateLabel()};gainSkill('Survival',14);msg='You followed the trail cautiously. A hunt is now ready in Adventure; choose whether to pursue it or let the creature go.';break}
 case'path_tracks:mark':dayPass(1,'trail marking');energyCost(4);c.coin+=12;c.reputation=clamp(c.reputation+1,-100,100);gainSkill('Survival',12);msg='You marked the track and warned travelers. The small reward came without disturbing the animal.';break;
 case'path_escort:accept':dayPass(3,'escort contract');energyCost(12);{const pay=34+Math.floor(Math.random()*12);c.coin+=pay;gainSkill('Combat',12);gainSkill('Survival',10);msg=`You escorted the caravan to a safe checkpoint and received ${coins(pay)}. The work taught you to stay alert without picking unnecessary fights.`}break;
 case'path_escort:spar':state.pendingEvent=null;startCombat('bandit',{type:'spar',label:'controlled practice bout',noLoot:true,training:true});addFeed('⚔️','Practice bout accepted','You chose a controlled spar instead of a road contract. A trained opponent is ready in Adventure.');persist();render();toast('Practice bout started.');return true;
 case'path_salvage:sort':dayPass(1,'salvage sorting');energyCost(6);{const success=(c.skills.Crafting?.level||1)+(c.attrs.Intelligence||10)/5>=4;const count=success?3:1;c.inventory.scrap=(c.inventory.scrap||0)+count;c.coin+=success?8:3;gainSkill('Crafting',18);msg=`You sorted the pile and kept ${count} useful scrap piece${count===1?'':'s'}${success?' plus a small buyer’s fee':''}.`}break;
 case'path_salvage:share':dayPass(1,'shared salvage');energyCost(5);c.coin+=10;c.reputation=clamp(c.reputation+2,-100,100);c.pathProgress.contactReputation.locals=clamp((c.pathProgress.contactReputation.locals||0)+1,-10,20);gainSkill('Trade',12);msg='You made a fair split with the workshop and gained a little local trust.';break;
 case'path_contract:sabotage':{dayPass(2,'shadow contract');energyCost(12);const check=(c.skills.Magic?.level||1)+(c.skills.Lore?.level||1)+(c.attrs.Wisdom||10)/6;const success=Math.random()<clamp(.48+(check-4)*.06,.2,.92);const reward=success?42:16;c.coin+=reward;c.pathProgress.contactReputation.shadow=clamp((c.pathProgress.contactReputation.shadow||0)+(success?2:0),-10,20);if(success){msg=`The curse disrupted the rival shipment without harming anyone directly. You earned ${coins(reward)}. A small rumor of occult interference may persist.`;gainSkill('Magic',24);gainSkill('Lore',12)}else{c.reputation=clamp(c.reputation-3,-100,100);msg=`Your interference was noticed. You earned only ${coins(reward)} and local trust fell.`;gainSkill('Magic',10)}break}
 case'path_contract:cleanse':dayPass(2,'curse removal');energyCost(10);{const success=(c.skills.Magic?.level||1)+(c.skills.Lore?.level||1)>=5;const pay=success?32:18;c.coin+=pay;c.reputation=clamp(c.reputation+1,-100,100);gainSkill('Magic',20);gainSkill('Lore',18);msg=`You treated the shipment instead of sabotaging it. Earned ${coins(pay)} and strengthened your reputation as an occult professional.`}break;
 case'path_sample:sample':dayPass(2,'material sampling');energyCost(9);c.inventory.herb=(c.inventory.herb||0)+1;c.inventory.potion=(c.inventory.potion||0)+1;gainSkill('Lore',22);gainSkill('Crafting',12);msg='You collected a compatible sample and prepared a minor healing potion. The alchemist paid fairly for your careful work.';c.coin+=12;break;
 case'path_sample:teach':dayPass(2,'research assistance');energyCost(8);c.coin+=26;gainSkill('Lore',22);c.pathProgress.contactReputation.arcane=clamp((c.pathProgress.contactReputation.arcane||0)+1,-10,20);msg='You helped document a safe material-handling procedure and earned coin plus an alchemist contact.';break;
 default:if(choice==='leave'){msg='You declined the opportunity. No penalty was imposed.';break}return false;
 }if(choice==='leave'){c.pathHistory=Array.isArray(c.pathHistory)?c.pathHistory:[];c.pathHistory.unshift({title:e.title,choice,date:dateLabel(),detail:msg||'You declined the opportunity.'});c.pathHistory=c.pathHistory.slice(0,50);addFeed(RACES[c.race].icon,e.title,msg||'You declined the opportunity.','activity');state.pendingEvent=null;state.eventQueue=Array.isArray(state.eventQueue)?state.eventQueue:[];if(state.eventQueue.length)state.pendingEvent=state.eventQueue.shift();persist();render();toast('You declined the opportunity.');return true}c.pathProgress=c.pathProgress||{offersTaken:0,contractsCompleted:0,contactReputation:{},flags:[]};c.pathProgress.contractsCompleted=(c.pathProgress.contractsCompleted||0)+1;state.character.pathHistory=Array.isArray(state.character.pathHistory)?state.character.pathHistory:[];state.character.pathHistory.unshift({title:e.title,choice,date:dateLabel(),detail:msg});state.character.pathHistory=state.character.pathHistory.slice(0,50);addFeed(RACES[c.race].icon,e.title,msg,'milestone');state.pendingEvent=null;state.eventQueue=Array.isArray(state.eventQueue)?state.eventQueue:[];if(state.eventQueue.length)state.pendingEvent=state.eventQueue.shift();persist();render();toast('Your decision has been recorded.');return true}
chooseEvent = function(choice){const id=state?.pendingEvent;if(id&&id.startsWith('path_')){irFinishPathEvent(id,choice);return}return irV02ChooseEvent(choice)}

// Turn-based combat — all changes are written into the same character and world save.
let startCombat;
function irCurrentDefense(){const c=state.character;return Math.floor((c.attrs.Vitality||10)/7)+(c.equipment?.armor==='leather_armor'?3:0)+(c.equipment?.offhand==='shield'?2:0)+(c.injuries?.some(i=>i.id==='wounded')?-1:0)}
function irEquippedWeapon(){const id=state?.character?.equipment?.weapon;return IR_WEAPON_DATA[id]||{damage:1,magic:0}}
function irEnemyForSite(forceId=null){const s=site();if(forceId&&IR_ENEMIES[forceId])return IR_ENEMIES[forceId];let pool=irBiomeEncounterIds(s);if(s?.type==='settlement')pool=(state.character.reputation<=-5?['guard','thief','bandit']:['thief','bandit','goblin']);let danger=Number(s?.risk)||10;if(danger>38)pool=pool.concat(['direwolf','ogre','troll','wight']);else if(danger>27)pool=pool.concat(['direwolf','ogre','cultist']);const c=state.character;if(c.race==='demonkin'&&pool.includes('cultist'))pool=pool.concat(['cultist']);const id=pool[Math.floor(Math.random()*pool.length)];return IR_ENEMIES[id]||IR_ENEMIES.goblin}
startCombat = function(enemyId=null,source={type:'wild'}){const c=state?.character;if(!c||state.combat?.active){toast(state.combat?.active?'You are already in combat.':'No active character.');return false}if(state.pendingEvent&&['ambush','hunt','dungeon'].includes(source.type)){state.eventQueue=Array.isArray(state.eventQueue)?state.eventQueue:[];if(!state.eventQueue.includes(state.pendingEvent))state.eventQueue.unshift(state.pendingEvent);state.pendingEvent=null}else if(state.pendingEvent&&!(source.type==='path'&&state.pendingEvent?.startsWith?.('path_'))){toast('Resolve the pending choice before starting a fight.');return false}const template=typeof enemyId==='string'?(IR_ENEMIES[enemyId]||null):null;const base=template||irEnemyForSite();const level=Math.max(1,c.skills.Combat?.level||1);const scale=clamp(1+(level-1)*.055,1,1.5);const hp=Math.round(base.hp*scale);state.combat={active:true,enemyId:base.id,enemyName:base.name,enemyIcon:base.icon,enemyDesc:base.desc,enemyHP:hp,enemyMaxHP:hp,enemyAttack:Math.round(base.attack*clamp(.9+(level-1)*.025,.9,1.35)),enemyDefense:base.defense,enemyXP:base.xp,enemyCoins:base.coins,enemyStyle:base.style,enemyBribe:base.bribe||0,enemyLoot:(base.loot||[]).slice(),round:1,guarding:false,playerStatuses:[],log:[`${base.name} blocks your way. Decide whether to attack, defend, use a skill, or find another way out.`],source:typeof source==='string'?{type:source}:source,startedAt:dateLabel(),enemyLevel:Math.max(1,Math.min(20,level)),enemyWinded:false};if(state.combat.source?.type==='dungeon')state.world.dungeon=state.world.dungeon||null;addFeed('⚔️','Combat begins',`${c.name} encountered ${base.name} at ${site().name}.`, 'warning');persist();state.view='Adventure';render();toast(`Encounter: ${base.name}.`);return true}
function irBattleLog(text){const b=state.combat;if(!b)return;b.log.unshift(text);b.log=b.log.slice(0,9)}
function irCombatEnd(kind,detail=''){const b=state.combat;if(!b)return;const c=state.character;const source=b.source||{type:'wild'};if(kind==='victory'){c.combatStats=c.combatStats||{wins:0,defeats:0,escapes:0,monstersDefeated:0,totalExperience:0};c.combatStats.wins++;c.combatStats.monstersDefeated++;c.combatStats.totalExperience+=b.enemyXP||0;const xp=b.enemyXP||20;gainSkill('Combat',xp);if(source.type==='hunt')gainSkill('Survival',Math.max(8,Math.floor(xp*.45)));let reward=0;if(!source.noLoot&&source.type!=='spar'){reward=rand(b.enemyCoins?.[0]??2,b.enemyCoins?.[1]??8);c.coin+=reward;const loot=b.enemyLoot||[];if(loot.length&&Math.random()<.62){const item=loot[Math.floor(Math.random()*loot.length)];c.inventory[item]=(c.inventory[item]||0)+1;detail+=(detail?' ':'')+`Recovered ${ITEMS[item]?.name||item}.`}if(reward)detail+=(detail?' ':'')+`Gained ${coins(reward)} and ${xp} combat experience.`}else detail+=(detail?' ':'')+`Gained ${xp} combat experience.`;const s=site();s.changes=s.changes||{};s.changes.clearedThreats=Array.isArray(s.changes.clearedThreats)?s.changes.clearedThreats:[];s.changes.clearedThreats.push(`${b.enemyId}-${state.character.daysLived}`);if(source.type==='dungeon'){const d=state.world.dungeon;if(d){if(source.room==='guardian'){d.cleared=true;d.stage='done';d.entered=false;state.world.insideDungeon=false;d.completedAt=dateLabel();d.visits=(d.visits||0)+1;s.changes.dungeonCleared=true;irRecordDiscovery(`Cleared ${d.name}`,`You defeated the vault guardian and completed the dungeon at ${s.name}.`,s.id,'🏆')}else if(source.room==='guard'){d.stage=d.route==='left'?'boss':'treasure'}else d.stage='guard';}}if(source.type==='hunt'){c.huntTrophies=Array.isArray(c.huntTrophies)?c.huntTrophies:[];c.huntTrophies.unshift({enemyId:b.enemyId,name:b.enemyName,date:dateLabel(),siteId:s.id});c.huntTrophies=c.huntTrophies.slice(0,40);if(b.enemyId==='wolf'||b.enemyId==='direwolf'||b.enemyId==='boar')c.inventory.wolf_fang=(c.inventory.wolf_fang||0)+1;if(b.enemyId==='spider')c.inventory.spider_silk=(c.inventory.spider_silk||0)+1;}addFeed('🏆',`${b.enemyName} defeated`,detail||'The threat is gone for now. Your results have been recorded.','milestone');}
 else if(kind==='escape'){c.combatStats=c.combatStats||{wins:0,defeats:0,escapes:0,monstersDefeated:0,totalExperience:0};c.combatStats.escapes++;addFeed('💨','Escaped combat',`${c.name} escaped ${b.enemyName}. No victory rewards were received. ${detail}`,'activity');if(source.type==='hunt')state.hunt=null;}
 else {c.combatStats=c.combatStats||{wins:0,defeats:0,escapes:0,monstersDefeated:0,totalExperience:0};c.combatStats.defeats++;c.health=1;c.energy=clamp(c.energy-12,0,c.maxEnergy);c.injuries=Array.isArray(c.injuries)?c.injuries:[];c.injuries.push({id:'wounded',name:'Wounded',days:4,detail:'A recoverable injury from a defeat. Rest or visit a healer to recover.'});addFeed('🩹','Defeated but alive',`${c.name} was overwhelmed by ${b.enemyName}. You escaped with 1 health, lost energy, and suffered a recoverable injury. ${detail}`,'warning');}
 state.combat=null;if(source.type==='hunt'&&kind!=='victory')state.hunt=null;state.eventQueue=Array.isArray(state.eventQueue)?state.eventQueue:[];if(!state.pendingEvent&&state.eventQueue.length)state.pendingEvent=state.eventQueue.shift();persist();render();toast(kind==='victory'?'Victory! Your rewards were saved.':kind==='escape'?'You escaped the encounter.':'You were defeated, but survived.')}
function irEnemyTurn(){const b=state.combat,c=state.character;if(!b?.active)return;let statusMsg='';for(const st of (b.playerStatuses||[]).slice()){if(st.id==='poison'||st.id==='bleed'||st.id==='curse'){const damage=st.id==='poison'?3:st.id==='bleed'?2:1;if(st.id==='curse'){c.energy=clamp(c.energy-3,0,c.maxEnergy);statusMsg+=`${st.name} drains 3 energy. `;}else{c.health=Math.max(0,c.health-damage);statusMsg+=`${st.name} deals ${damage} health damage. `;}st.turns--}}b.playerStatuses=(b.playerStatuses||[]).filter(x=>x.turns>0);if(statusMsg)irBattleLog(statusMsg.trim());if(c.health<=0){irCombatEnd('defeat','Ongoing status effects left you unable to continue.');return}if(b.enemyStyle==='regenerate')b.enemyHP=Math.min(b.enemyMaxHP,b.enemyHP+3);const spread=Math.floor(Math.random()*4);let raw=b.enemyAttack+spread;let effect='';if(b.enemyStyle==='heavy'||b.enemyStyle==='boss'){if(Math.random()<.24){raw+=4;effect='A crushing heavy blow lands. '}}if(b.enemyStyle==='trickster'&&Math.random()<.22){c.mood=clamp(c.mood-2,0,100);effect='The goblin throws dust in your face. '}if(b.enemyStyle==='steal'&&Math.random()<.28&&c.coin>0){const stolen=Math.min(c.coin,rand(1,Math.min(6,c.coin)));c.coin-=stolen;effect=`The thief snatches ${coins(stolen)} during the scramble. `}const defense=irCurrentDefense();let damage=Math.max(1,raw-defense);if(b.guarding)damage=Math.max(1,Math.ceil(damage*.45));c.health=Math.max(0,c.health-damage);irBattleLog(`${effect}${b.enemyName} deals ${damage} damage${b.guarding?' through your guard':''}.`);b.guarding=false;if((b.enemyStyle==='poison'||b.enemyStyle==='acid')&&Math.random()<.24&&!b.playerStatuses.some(x=>x.id==='poison')){b.playerStatuses.push({id:'poison',name:'Poison',turns:3});irBattleLog('A venomous sting leaves poison in your system.')}if((b.enemyStyle==='bleed'||b.enemyStyle==='charge')&&Math.random()<.18&&!b.playerStatuses.some(x=>x.id==='bleed')){b.playerStatuses.push({id:'bleed',name:'Bleeding',turns:2});irBattleLog('The hit leaves a bleeding wound.')}if(b.enemyStyle==='curse'&&Math.random()<.24){c.energy=clamp(c.energy-5,0,c.maxEnergy);if(!b.playerStatuses.some(x=>x.id==='curse'))b.playerStatuses.push({id:'curse',name:'Curse drain',turns:2});irBattleLog('Dark energy drains your stamina.')}if(c.health<=0){irCombatEnd('defeat','The enemy landed the final blow.');return}b.round++;persist();render()}
function irBattleMove(move,itemId){const b=state?.combat,c=state?.character;if(!b?.active||!c)return;const weapon=irEquippedWeapon();const skillLevel=c.skills.Combat?.level||1;const strength=c.attrs.Strength||10;const agility=c.attrs.Agility||10;const wisdom=c.attrs.Wisdom||10;let end=false;
 if(move==='attack'){let damage=Math.max(2,Math.floor(strength*.42+skillLevel*2+weapon.damage+Math.random()*5-b.enemyDefense));if(b.enemyId==='slime'&&weapon.damage>0)damage=Math.max(1,Math.floor(damage*.75));b.enemyHP=Math.max(0,b.enemyHP-damage);irBattleLog(`You strike ${b.enemyName} for ${damage} damage.`);gainSkill('Combat',4)}
 else if(move==='defend'){b.guarding=true;irBattleLog('You set your feet and prepare to absorb the next attack.');}
 else if(move==='power'){if(c.energy<12){toast('You need 12 energy for a Power Strike.');return}c.energy-=12;let damage=Math.max(3,Math.floor(strength*.62+skillLevel*2.8+weapon.damage+Math.random()*6-b.enemyDefense));b.enemyHP=Math.max(0,b.enemyHP-damage);irBattleLog(`Power Strike lands for ${damage} damage. It costs 12 energy.`);gainSkill('Combat',7)}
 else if(move==='magic'){if(c.energy<15){toast('You need 15 energy for an Arcane Bolt.');return}c.energy-=15;const weaponMagic=weapon.magic||0;let damage=Math.max(4,Math.floor(wisdom*.48+(c.skills.Magic?.level||1)*3+weaponMagic+Math.random()*5-(b.enemyId==='slime'?0:b.enemyDefense*.35)));if(b.enemyId==='skeleton'||b.enemyId==='wight'||b.enemyId==='guardian')damage=Math.floor(damage*1.25);b.enemyHP=Math.max(0,b.enemyHP-damage);irBattleLog(`Arcane Bolt deals ${damage} magical damage. It costs 15 energy.`);gainSkill('Magic',7)}
 else if(move==='item'){if(!itemId||!(c.inventory[itemId]>0)){toast('You do not have that item.');return}if(itemId==='bandage'){c.inventory.bandage--;const healed=Math.min(c.maxHealth-c.health,Math.round(30*(race().mods.heal||1)));c.health+=healed;irBattleLog(`You apply a field bandage and recover ${healed} health.`)}else if(itemId==='potion'){c.inventory.potion--;const healed=Math.min(c.maxHealth-c.health,38);c.health+=healed;irBattleLog(`You drink a minor healing potion and recover ${healed} health.`)}else if(itemId==='bread'){c.inventory.bread--;c.hunger=clamp(c.hunger+20,0,100);c.energy=clamp(c.energy+3,0,c.maxEnergy);irBattleLog('You eat trail bread. Hunger improves, but you lose the chance to attack this turn.')}else if(itemId==='smoke_bomb'){c.inventory.smoke_bomb--;const chance=.88+agility*.002;if(Math.random()<chance){irBattleLog('The smoke bomb creates an opening. You escape!');irCombatEnd('escape','The smoke hides your retreat.');return}irBattleLog('The smoke covers the room, but the enemy finds you before you escape.')}else if(itemId==='potion'){}else{toast('That item has no battle use.');return}}
 else if(move==='escape'){const chance=clamp(.38+agility*.018+(c.skills.Survival?.level||1)*.025-(site().risk||10)*.002, .12,.86);if(Math.random()<chance){irBattleLog('You find an opening and escape.');irCombatEnd('escape','You chose retreat over a dangerous fight.');return}irBattleLog('You fail to escape and leave yourself exposed.');}
 else if(move==='hide'){const chance=clamp(.3+(c.attrs.Perception||10)*.012+(c.skills.Survival?.level||1)*.025-(site().risk||10)*.001,.15,.82);if(Math.random()<chance){irBattleLog('You break line of sight and slip away.');irCombatEnd('escape','You hid long enough to get clear.');return}irBattleLog('The enemy spots your movement.');}
 else if(move==='negotiate'){const chance=clamp(.22+(c.attrs.Charisma||10)*.018+(c.skills.Social?.level||1)*.035+(c.reputation||0)*.002+(c.race==='goblin'&&b.enemyId==='goblin'?.15:0),.05,.78);if(!['goblin','bandit','thief','guard','cultist'].includes(b.enemyId)){toast('This creature is unlikely to understand negotiation.');return}if(Math.random()<chance){irBattleLog(`You find terms that convince ${b.enemyName} to stand down.`);irCombatEnd('escape','A non-combat solution worked.');return}irBattleLog('Your offer fails. The enemy presses the attack.');}
 else if(move==='bribe'){if(!b.enemyBribe||c.coin<b.enemyBribe){toast(`This opponent requires ${b.enemyBribe||'no'} coins to consider a bribe, and you do not have enough.`);return}const price=b.enemyBribe;c.coin-=price;irBattleLog(`You pay ${coins(price)} to end the confrontation.`);irCombatEnd('escape','You paid to avoid further conflict.');return}
 if(!state.combat?.active)return;if(b.enemyHP<=0){irCombatEnd('victory',`${b.enemyName} was defeated.`);return}irEnemyTurn()}
function irCombatPanel(){const b=state.combat,c=state.character;if(!b?.active)return '';const pctEnemy=Math.max(0,Math.min(100,100*b.enemyHP/b.enemyMaxHP)),pctPlayer=Math.max(0,Math.min(100,100*c.health/c.maxHealth));const statuses=(b.playerStatuses||[]).map(s=>`<span class="tag warning">${esc(s.name)} · ${s.turns}</span>`).join('');const nonCombat=['goblin','bandit','thief','guard','cultist'].includes(b.enemyId);const price=b.enemyBribe>0?`<button class="button small" data-action="battle-move" data-move="bribe" ${c.coin<b.enemyBribe?'disabled':''}>Pay ${b.enemyBribe} ◈</button>`:'';const consumables=['bandage','potion','bread','smoke_bomb'].filter(id=>(c.inventory[id]||0)>0);return `<section class="panel panel-pad ir-combat-panel"><div class="panel-heading"><div><div class="eyebrow" style="color:var(--red,#e58f82)">TURN-BASED ENCOUNTER · ROUND ${b.round}</div><h2>${b.enemyIcon} ${esc(b.enemyName)}</h2><p>${esc(b.enemyDesc)}</p></div><span class="tag warning">${b.enemyLevel>1?'THREAT LV. '+b.enemyLevel:'THREAT'}</span></div><div class="ir-battle-bars"><div><div class="ir-bar-label"><strong>Opponent</strong><b>${b.enemyHP}/${b.enemyMaxHP} HP</b></div><div class="ir-bar"><span class="enemy" style="width:${pctEnemy}%"></span></div></div><div><div class="ir-bar-label"><strong>${esc(c.name)}</strong><b>${c.health}/${c.maxHealth} HP · ${c.energy} EN</b></div><div class="ir-bar"><span class="player" style="width:${pctPlayer}%"></span></div></div></div><div class="ir-battle-status">${statuses||'<span class="tag">No status effects</span>'}<span class="tag">Defense ${irCurrentDefense()} · Weapon ${esc(c.equipment?.weapon?ITEMS[c.equipment.weapon]?.name||c.equipment.weapon:'Unarmed')}</span></div><div class="ir-battle-actions"><button class="button primary" data-action="battle-move" data-move="attack">⚔️ Attack</button><button class="button" data-action="battle-move" data-move="defend">🛡️ Defend</button><button class="button" data-action="battle-move" data-move="power">💥 Power Strike · 12 EN</button><button class="button" data-action="battle-move" data-move="magic" ${c.energy<15?'disabled':''}>✨ Arcane Bolt · 15 EN</button><button class="button subtle" data-action="battle-move" data-move="hide">👁️ Hide</button><button class="button subtle" data-action="battle-move" data-move="escape">↩ Escape</button>${nonCombat?`<button class="button subtle" data-action="battle-move" data-move="negotiate">💬 Negotiate</button>`:''}${price}</div>${consumables.length?`<div class="ir-battle-consumables"><span class="tiny-label">USE ITEM</span>${consumables.map(id=>`<button class="button small" data-action="battle-move" data-move="item" data-item="${id}">${ITEMS[id].icon} ${ITEMS[id].name} ×${c.inventory[id]}</button>`).join('')}</div>`:''}<div class="ir-battle-log"><div class="tiny-label">COMBAT LOG</div>${b.log.map((t,i)=>`<p class="${i===0?'latest':''}">${esc(t)}</p>`).join('')}</div><div class="notice">Combat is turn-based. Defending halves the next hit; status effects can deal damage over time. Retreat is always available, and defeat causes a recoverable injury rather than ending your life.</div></section>`}
function irBattleStartFromWarning(){if(!state.warning)return;const id=state.warning.enemyId;state.warning=null;startCombat(id,{type:'ambush'});}
function irAvoidWarning(){const w=state.warning;if(!w)return;const c=state.character;const chance=clamp(.72+(c.attrs.Perception||10)*.008+(c.skills.Survival?.level||1)*.012-(site().risk||10)*.003,.35,.95);state.warning=null;if(Math.random()<chance){c.energy=clamp(c.energy-2,0,c.maxEnergy);gainSkill('Survival',6);addFeed('👣','Danger avoided',`You took a quieter route around ${w.enemyName||'the threat'} at ${site().name}.`);toast('You avoided the danger.')}else{addFeed('⚠️','The threat closes in',`Your attempt to avoid ${w.enemyName||'the threat'} failed.`,'warning');startCombat(w.enemyId,{type:'ambush'})}persist();render()}
function irExplore(mode='scout'){if(mode==='forage')return irV02Explore('forage');const c=state.character,s=site();if(!c||!s||state.combat?.active)return;if(!actionCost(15))return;c.energy=clamp(c.energy-15,0,c.maxEnergy);dayPass(2,'scouting');s.changes=s.changes||{};s.changes.searches=(s.changes.searches||0)+1;s.changes.scouted=true;for(const rt of (typeof ir0775ConnectionsFrom==='function'?ir0775ConnectionsFrom(s.id):[]))irAddKnownLocation(rt.to);const first=!s.changes.firstScout;s.changes.firstScout=true;const danger=clamp(.10+(s.risk||10)/190-(c.attrs.Perception||10)*.004-(c.skills.Survival?.level||1)*.012, .035,.52);if(Math.random()<danger){const pool=(irBiomeEncounterIds(s)).filter(id=>!(s.changes.clearedThreats||[]).some(x=>String(x).startsWith(id+'-')&&Number(String(x).slice(id.length+1))>=(state.character.daysLived-30)));const id=(pool.length?pool:irBiomeEncounterIds('woodland'))[Math.floor(Math.random()*(pool.length?pool:irBiomeEncounterIds('woodland')).length)];if((c.attrs.Perception||10)+(c.skills.Survival?.level||1)*2>=18){state.warning={enemyId:id,enemyName:IR_ENEMIES[id].name,siteId:s.id,message:`You noticed movement before it got close. Your scouting and Survival skill gave you time to choose.`};addFeed('👁️','A danger spotted in time',`${IR_ENEMIES[id].name} is nearby, but you noticed it first.`,'warning')}else{addFeed('⚠️','An ambush!',`${IR_ENEMIES[id].name} caught you unaware.`,'warning');startCombat(id,{type:'ambush'})}}else{const lootPool=irBiomeResourceItems(s,'scout');const item=lootPool[Math.floor(Math.random()*lootPool.length)];c.inventory[item]=(c.inventory[item]||0)+1;const pay=first?rand(5,9):rand(1,4);c.coin+=pay;gainSkill('Survival',first?17:9);addFeed('🔎',first?`Surveyed ${s.name}`:'A familiar area',`You found ${ITEMS[item]?.name||item} and ${coins(pay)} while searching ${irBiomeProfileForSite(s).name.toLowerCase()} ground.`);if(first)irRecordDiscovery(`Scouted ${s.name}`,`You marked routes and identified resources around ${s.name}.`,s.id,'🔎')}s.changes.notes=Array.isArray(s.changes.notes)?s.changes.notes:[];s.changes.notes.unshift({date:dateLabel(),activity:'scout'});s.changes.notes=s.changes.notes.slice(0,20);persist();render();if(!state.combat?.active)toast('Scouting complete. Local risk and discoveries were recorded.')}
explore = function(mode='scout'){return irExplore(mode)}
function irStartHunt(){const c=state.character,s=site();if(state.pendingEvent){toast('Resolve the current event choice before beginning a hunt.');return}if(state.combat?.active||state.hunt){toast(state.hunt?'You already have a trail to investigate.':'Finish combat first.');return}if(!actionCost(10))return;c.energy=clamp(c.energy-10,0,c.maxEnergy);dayPass(1,'tracking a hunt');const pool=(irBiomeEncounterIds(s)).filter(id=>['wolf','spider','boar','direwolf','slime','goblin'].includes(id));const id=pool[Math.floor(Math.random()*pool.length)];const quality=clamp((c.skills.Survival?.level||1)+(c.attrs.Perception||10)/3+((race().mods.perception||1)-1)*8,1,30);state.hunt={enemyId:id,quality,siteId:s.id,origin:'hunting',startedAt:dateLabel(),prepared:false};gainSkill('Survival',12);if(quality>=10)addFeed('🐾','Clear tracks found',`You identified the trail of a ${IR_ENEMIES[id].name.toLowerCase()} before pursuing it. You can prepare, pursue, or abandon the hunt.`);else addFeed('🐾','A faint trail',`You found signs of a ${IR_ENEMIES[id].name.toLowerCase()}, but the trail is uncertain. Preparation would be wise.`);persist();render();toast('Tracks found. Adventure now has a hunting choice.')}
function irHuntAction(action){const h=state.hunt;if(!h)return;const c=state.character;if(action==='leave'){state.hunt=null;addFeed('👣','Hunt abandoned','You left the trail alone and avoided unnecessary risk.');persist();render();return}if(action==='prepare'){if(c.energy<8){toast('You need 8 energy to prepare for the hunt.');return}c.energy-=8;c.inventory.bread=(c.inventory.bread||0)+0;if(c.inventory.bandage===undefined)c.inventory.bandage=0;h.prepared=true;h.quality+=4;addFeed('🎒','Prepared for the hunt','You checked your stance, route, and supplies. The first strike is less likely to catch you off guard.');persist();render();return}if(action==='pursue'){if(!actionCost(5))return;c.energy=clamp(c.energy-5,0,c.maxEnergy);const enemy=h.enemyId;const source={type:'hunt',prepared:!!h.prepared,quality:h.quality,siteId:h.siteId};state.hunt=null;startCombat(enemy,source);if(source.prepared&&state.combat){state.combat.enemyWinded=true;state.combat.enemyHP=Math.max(1,state.combat.enemyHP-4);irBattleLog('Your preparation gave you the first opening. The enemy starts slightly weakened.');persist();render()}return}}
function irDiscoverDungeon(){const c=state.character,s=site();if(state.world.dungeon?.discovered){toast(`You already found ${state.world.dungeon.name}. Return to ${irSiteById(state.world.dungeon.siteId)?.name||'its entrance'} to continue.`);return}if(!actionCost(12))return;c.energy=clamp(c.energy-12,0,c.maxEnergy);dayPass(2,'investigating ruins');const rng=irRng(`${state.world.seed}|${s.id}|${c.race}|vault-v3`);const roomTexts=[['The Split Passage','Two routes descend: a safer left stair with signs of a guard, and a flooded crawlspace with a trap warning and a chance of greater treasure.'],['The Sighing Hall','Old mechanisms lie beneath dust. The floor is cracked where a pressure plate may be hidden.'],['The Guard Chamber','An animated sentinel or paid keeper protects the path deeper inside.'],['The Forgotten Cache','A sealed niche holds old coins and a relic, if you can reach it safely.'],['The Heart Vault','A stone guardian protects the dungeon’s final sealed chamber.']];const name=`${['Rootbound','Moonlit','Ashen','Moss-Crowned','Whispering'][Math.floor(rng()*5)]} ${['Cellar','Vault','Burial Hall','Watch','Reliquary'][Math.floor(rng()*5)]}`;state.world.dungeon={id:`dungeon-${s.id}`,name,siteId:s.id,discovered:true,entered:false,cleared:false,stage:'entrance',route:null,roomTexts,history:[],createdAt:dateLabel(),seed:`${state.world.seed}-${s.id}`};s.changes.dungeonFound=true;irRecordDiscovery(`Discovered ${name}`,`You found a hidden entrance at ${s.name}. The entrance is saved in your world journal.`,s.id,'⛏️');addFeed('⛏️','A dungeon entrance found',`${name} lies beneath or beyond ${s.name}. Its connected rooms have a branching route, a trap, a treasure cache, and a final guardian.`,'discovery');persist();render();toast(`Dungeon discovered: ${name}.`)}
function irEnterDungeon(){const d=state.world.dungeon;if(!d?.discovered||d.cleared){toast(d?.cleared?'This dungeon has already been cleared.':'No dungeon entrance has been discovered yet.');return}if(site().id!==d.siteId){toast(`Travel back to ${irSiteById(d.siteId)?.name||'the entrance'} to enter the dungeon.`);return}if(state.combat?.active)return;d.entered=true;if(d.stage==='entrance')d.stage='branch';state.world.insideDungeon=true;addFeed('⛏️',`Entered ${d.name}`,`You descended into the dungeon. Each room offers a choice; you can retreat between encounters.`);persist();render();toast('Dungeon expedition started.')}
function irDungeonChoice(choice){const d=state.world.dungeon,c=state.character;if(!d?.entered||d.cleared)return;if(d.stage==='branch'){if(choice==='left'){d.route='left';d.stage='guard';d.history.push('Took the sealed left stair, avoiding the pressure-plate hall but passing a guarded chamber.');addFeed('🧭','Dungeon route chosen','You took the narrow left stair. The trap hall is bypassed, but the guard ahead is better prepared.')}else if(choice==='right'){d.route='right';d.stage='trap';d.history.push('Took the flooded right crawlspace toward a possible treasure cache.');addFeed('🧭','Dungeon route chosen','You took the flooded crawlspace. It may contain a trap, but it leads toward the forgotten cache.')}}else if(d.stage==='trap'){if(choice==='disarm'){const check=(c.skills.Survival?.level||1)+(c.attrs.Perception||10)/4+(c.attrs.Intelligence||10)/4;dayPass(1,'trap disarming');c.energy=clamp(c.energy-6,0,c.maxEnergy);if(check>=6||Math.random()<.45){d.stage='guard';gainSkill('Survival',20);d.history.push('Disarmed the pressure trap.');addFeed('🪤','Trap disarmed','You spotted the trigger and disabled the mechanism.')}else{c.health=Math.max(1,c.health-12);d.stage='guard';c.injuries.push({id:'sprained',name:'Sprained',days:2,detail:'A strain from a trap. It recovers with time.'});addFeed('🩹','Trap triggered','You failed to disable the trigger and took a recoverable injury.','warning')}}else if(choice==='rush'){dayPass(1,'rushing past a trap');c.health=Math.max(1,c.health-9);c.energy=clamp(c.energy-10,0,c.maxEnergy);d.stage='guard';d.history.push('Rushed past the trap and took damage.');addFeed('🪤','Trap sprung','You reached the far side, but not before the mechanism struck you.','warning')}else if(choice==='detour'){dayPass(2,'dungeon detour');c.energy=clamp(c.energy-7,0,c.maxEnergy);d.stage='guard';d.history.push('Spent longer finding a route around the trap.');addFeed('🧭','Trap bypassed','You took the long way around and kept most of your health.')}}else if(d.stage==='treasure'){if(choice==='claim'){const relic=Math.random()<.7?'dungeon_relic':'curse_shard';c.inventory[relic]=(c.inventory[relic]||0)+1;c.coin+=rand(8,18);d.history.push(`Claimed the cache and found ${ITEMS[relic].name}.`);addFeed('💎','Treasure cache found',`You recovered ${ITEMS[relic].name.toLowerCase()} and a purse of coins.`);d.stage='boss'}else if(choice==='skip'){d.stage='boss';d.history.push('Skipped the cache and moved toward the final vault.');addFeed('↗️','Treasure left behind','You chose to conserve time and supplies rather than open the cache.')}}if(d.stage==='guard'&&choice==='fight-guard'){startCombat(d.route==='left'?'cultist':'skeleton',{type:'dungeon',room:'guard'});return}if(d.stage==='boss'&&choice==='fight-boss'){startCombat('guardian',{type:'dungeon',room:'guardian'});return}if(choice==='retreat'){d.entered=false;state.world.insideDungeon=false;addFeed('↩','Dungeon retreat','You returned to the surface. Your room progress and discovered entrance remain saved.')}persist();render();toast('Dungeon choice recorded.')}
function irDungeonPanel(){const d=state.world.dungeon;if(!d?.discovered)return `<section class="panel panel-pad"><div class="panel-heading"><div><div class="eyebrow">DUNGEON DISCOVERY</div><h3>Investigate local ruins</h3><p>Spend two days looking for a hidden ruin or underground entrance near ${esc(site().name)}.</p></div><span class="tag">UNKNOWN SITE</span></div><p class="ir-panel-copy">The first dungeon is modest but complete: branching paths, a trap, a guarded chamber, a treasure cache, and a final guardian. It persists with your world.</p><button class="button primary" data-action="discover-dungeon">Investigate for an entrance · 2 days</button></section>`;const atEntrance=site().id===d.siteId;let body='';if(d.cleared)body=`<div class="notice">Dungeon cleared. Its state remains recorded in the world journal. You can return to the entrance, but the guardian and treasure will not reset.</div>`;else if(!atEntrance)body=`<div class="notice">Entrance found at ${esc(irSiteById(d.siteId)?.name||'an unknown place')}. Travel back there to continue the expedition.</div>`;else if(!d.entered)body=`<p class="ir-panel-copy">You found ${esc(d.name)} here. Its exploration progress is saved. Enter when your health and supplies are ready.</p><button class="button primary" data-action="enter-dungeon">Enter dungeon</button>`;else if(d.stage==='branch')body=`<p class="ir-panel-copy">Two routes descend from the entry chamber. One avoids an obvious trap but passes a stronger guard; the other is longer and may lead to a treasure cache.</p><div class="ir-choice-row"><button class="button" data-action="dungeon-choice" data-choice="left">Left stair · bypass trap</button><button class="button" data-action="dungeon-choice" data-choice="right">Flooded crawlspace · treasure route</button><button class="button subtle" data-action="dungeon-choice" data-choice="retreat">Retreat</button></div>`;else if(d.stage==='trap')body=`<p class="ir-panel-copy">A pressure plate and old dart channels cross the hall.</p><div class="ir-choice-row"><button class="button primary" data-action="dungeon-choice" data-choice="disarm">Disarm carefully</button><button class="button" data-action="dungeon-choice" data-choice="rush">Rush through</button><button class="button subtle" data-action="dungeon-choice" data-choice="detour">Spend time finding a detour</button><button class="button subtle" data-action="dungeon-choice" data-choice="retreat">Retreat</button></div>`;else if(d.stage==='guard')body=`<p class="ir-panel-copy">A hostile guardian blocks the onward passage. Prepare before challenging it.</p><button class="button primary" data-action="dungeon-choice" data-choice="fight-guard">Fight the chamber guardian</button><button class="button subtle" data-action="dungeon-choice" data-choice="retreat">Retreat to surface</button>`;else if(d.stage==='treasure')body=`<p class="ir-panel-copy">The guarded chamber opens onto a forgotten cache. Take the risk for an extra reward or move directly to the final chamber.</p><div class="ir-choice-row"><button class="button primary" data-action="dungeon-choice" data-choice="claim">Open treasure cache</button><button class="button" data-action="dungeon-choice" data-choice="skip">Skip the cache</button></div>`;else if(d.stage==='boss')body=`<p class="ir-panel-copy">The Heart Vault opens. A stone guardian remains between you and clearing this place.</p><button class="button primary" data-action="dungeon-choice" data-choice="fight-boss">Challenge the final guardian</button><button class="button subtle" data-action="dungeon-choice" data-choice="retreat">Retreat to surface</button>`;return `<section class="panel panel-pad ir-dungeon-panel"><div class="panel-heading"><div><div class="eyebrow">FIRST DUNGEON · ${d.cleared?'CLEARED':`STAGE ${esc(d.stage.toUpperCase())}`}</div><h3>⛏️ ${esc(d.name)}</h3><p>${esc(d.cleared?'A completed expedition preserved in your journal.':`Entrance: ${irSiteById(d.siteId)?.name||'unknown location'} · Route: ${d.route||'not chosen yet'}`)}</p></div><span class="tag ${d.cleared?'gold':'warning'}">${d.cleared?'COMPLETE':'PERSISTENT RUN'}</span></div>${body}${d.history?.length?`<div class="ir-dungeon-history"><strong>Expedition chronicle</strong>${d.history.slice(-4).map(x=>`<p>• ${esc(x)}</p>`).join('')}</div>`:''}</section>`}
function irHuntPanel(){const h=state.hunt;if(!h)return '';const e=IR_ENEMIES[h.enemyId]||IR_ENEMIES.wolf;return `<section class="panel panel-pad ir-hunt-panel"><div class="panel-heading"><div><div class="eyebrow">HUNTING · TRACKS FOUND</div><h3>${e.icon} ${esc(e.name)} trail</h3><p>Your tracking quality is ${h.quality}. You can prepare before pursuit or leave the creature alone.</p></div><span class="tag gold">${esc(irBiomeProfileForSite(site()).name)}</span></div><div class="ir-choice-row"><button class="button primary" data-action="hunt-choice" data-choice="pursue">Pursue prey</button><button class="button" data-action="hunt-choice" data-choice="prepare" ${h.prepared?'disabled':''}>Prepare · 8 EN</button><button class="button subtle" data-action="hunt-choice" data-choice="leave">Abandon hunt</button></div></section>`}
function irWarningPanel(){const w=state.warning;if(!w)return '';return `<section class="panel panel-pad ir-warning-panel"><div class="panel-heading"><div><div class="eyebrow">DANGER DETECTED</div><h3>👁️ ${esc(w.enemyName||'Something nearby')}</h3><p>${esc(w.message||'You noticed movement before it got close.')}</p></div><span class="tag warning">YOU HAVE A MOMENT</span></div><div class="ir-choice-row"><button class="button primary" data-action="warning-fight">Prepare and face it</button><button class="button" data-action="warning-avoid">Avoid the threat</button><button class="button subtle" data-action="warning-track">Track it for a hunt</button></div></section>`}
renderAdventure = function(){const s=site(),c=state.character,active=state.combat?.active;return `${pageHead('Adventure & encounters','Scout the land, hunt wildlife, face threats on your terms, and prepare for a dungeon expedition.')}<section class="hero ir-adventure-hero"><div class="hero-content"><div class="avatar">${RACES[c.race].icon}</div><div><div class="eyebrow">${esc(RACES[c.race].name.toUpperCase())} · ${esc(c.lifePath||irPathProfile().path||'LIFE PATH')}</div><h2>${active?'A fight is underway':esc(s.name)}</h2><p>${active?'Choose a move each round. Health, energy, status effects, and the combat log update after each turn.':esc(irBiomeProfileForSite(s).name+' · '+s.desc)}</p><div class="hero-meta"><span class="tag gold">${s.risk}% LOCAL RISK</span><span class="tag">Combat Lv. ${c.skills.Combat?.level||1}</span><span class="tag">${c.combatStats?.wins||0} victories</span></div></div></div></section>${active?irCombatPanel():`${irWarningPanel()}${irHuntPanel()}<div class="grid two" style="margin-top:14px"><section class="panel panel-pad"><div class="panel-heading"><div><h3>Choose your approach</h3><p>Risk changes with the biome, local danger, skill, and preparation.</p></div><span class="tag warning">${s.risk}% RISK</span></div><div class="actions-grid">${actionCard('🔎','Scout for danger','Search for routes, resources, clues, and possible ambushes.','2 DAYS · 15 ENERGY','scout')}${actionCard('🐾','Start a hunt','Follow nearby tracks, prepare, then pursue prey if the risk is worth it.','1 DAY · 10 ENERGY','start-hunt')}${actionCard('🌿','Forage','Find food, herbs, and materials that suit this biome.','1 DAY · 8 ENERGY','forage')}${actionCard('🛡️','Practice defense','Gain Combat experience before seeking a dangerous fight.','1 DAY · 12 ENERGY','defense')}</div><div class="notice">You are not required to fight every threat. You can detect some ambushes, avoid danger, negotiate with intelligent opponents, pay certain enemies, or escape.</div></section><section class="panel panel-pad"><div class="panel-heading"><div><h3>Your combat record</h3><p>Victories, setbacks, and trophies stay with this character.</p></div><span class="tag">CHRONICLE</span></div><div class="ir-record-stats"><div><b>${c.combatStats?.wins||0}</b><span>Victories</span></div><div><b>${c.combatStats?.escapes||0}</b><span>Escapes</span></div><div><b>${c.combatStats?.defeats||0}</b><span>Defeats</span></div><div><b>${c.combatStats?.monstersDefeated||0}</b><span>Enemies down</span></div></div><p class="ir-panel-copy">Weapon: ${esc(c.equipment?.weapon?ITEMS[c.equipment.weapon]?.name||c.equipment.weapon:'Unarmed')} · Defense ${irCurrentDefense()} · Active injuries: ${(c.injuries||[]).filter(x=>x.days>0).map(x=>esc(x.name)).join(', ')||'none'}.</p><button class="button" data-tab="Inventory">Prepare in inventory</button></section></div>${irDungeonPanel()}<section class="panel panel-pad" style="margin-top:14px"><div class="panel-heading"><div><h3>Recent discoveries and trophies</h3><p>Hunts and scouting add notes to your chronicle.</p></div><span class="tag">FIELD NOTES</span></div>${(c.discoveries||[]).length?c.discoveries.slice(0,8).map(x=>`<div class="feed-item"><div class="feed-icon">${irSafeIcon(x.icon)}</div><div><strong>${esc(x.title)}</strong><p>${esc(x.detail)}</p><div class="feed-meta">${esc(x.date||'')}</div></div></div>`).join(''):'<div class="empty">No field discoveries yet. Scouting and hunting may add something to your record.</div>'}</section>`}`}
renderCharacter = function(){let html=irV02RenderCharacter();const c=state.character,b=irPathProfile(c.race,c.background);html=html.replace(/WORLD V2/g,'WORLD V3').replace(/VERSION 0\.2/g,'VERSION 0.4');html+=`<div class="grid two" style="margin-top:15px"><section class="panel panel-pad"><div class="panel-heading"><div><h3>Race & background identity</h3><p>These choices affect starting conditions, work, events, and combat.</p></div><span class="tag purple">VERSION 0.4</span></div><div class="feed-item"><div class="feed-icon">${RACES[c.race].icon}</div><div><strong>${esc(RACES[c.race].name)} · ${esc(b.name)}</strong><p>${esc(c.openingStory||b.opening||b.detail)}</p><p>Life path: ${esc(c.lifePath||b.path||'Independent')}</p></div></div><div class="notice">Race and background influence specialty job access, life-path contracts, combat bonuses, and the world’s starting response. They do not prohibit unrelated careers.</div></section><section class="panel panel-pad"><div class="panel-heading"><div><h3>Adventure record</h3><p>Combat and dungeon progress persist with your life.</p></div><span class="tag">SAVED</span></div><div class="ir-record-stats"><div><b>${c.combatStats?.wins||0}</b><span>Victories</span></div><div><b>${c.combatStats?.defeats||0}</b><span>Defeats</span></div><div><b>${c.combatStats?.escapes||0}</b><span>Escapes</span></div><div><b>${c.pathProgress?.contractsCompleted||0}</b><span>Contracts</span></div></div><p class="ir-panel-copy">${esc(state.world.dungeon?.name||'No dungeon discovered yet')}${state.world.dungeon?.cleared?' · cleared':''}</p></section></div>`;return html}
renderInventory = function(){return irV02RenderInventory().replace(/VERSION 0\.2/g,'VERSION 0.4')+`<section class="panel panel-pad" style="margin-top:14px"><div class="panel-heading"><div><h3>Equipment</h3><p>Equip a weapon or armor from your pack. Combat reads these slots directly.</p></div><span class="tag">LOADOUT</span></div><div class="ir-equipment-grid"><div><strong>Weapon</strong><p>${esc(state.character.equipment?.weapon?ITEMS[state.character.equipment.weapon]?.name||state.character.equipment.weapon:'Unarmed')} · ${irEquippedWeapon().damage||1} weapon damage</p></div><div><strong>Armor</strong><p>${esc(state.character.equipment?.armor?ITEMS[state.character.equipment.armor]?.name||state.character.equipment.armor:'None')} · reduces incoming damage</p></div><div><strong>Off-hand</strong><p>${esc(state.character.equipment?.offhand?ITEMS[state.character.equipment.offhand]?.name||state.character.equipment.offhand:'None')}</p></div></div><p class="ir-panel-copy">Use Equip in the inventory list to change your loadout. Some backgrounds start with a weapon; others begin with basic supplies.</p></section>`}
useItem = function(id){const c=state?.character;if(!c||!(c.inventory[id]>0))return;if(state.combat?.active){toast('Use combat items from the Adventure battle panel to spend the turn correctly.');return}if(IR_WEAPON_DATA[id]){const current=c.equipment?.weapon;c.equipment=c.equipment||{};c.equipment.weapon=current===id?null:id;addFeed(ITEMS[id].icon,current===id?'Weapon unequipped':'Weapon equipped',current===id?`You put away ${ITEMS[id].name}.`:`You equipped ${ITEMS[id].name}.`);persist();render();toast(current===id?'Weapon unequipped.':`${ITEMS[id].name} equipped.`);return}if(['shield','leather_armor'].includes(id)){c.equipment=c.equipment||{};const slot=id==='shield'?'offhand':'armor';c.equipment[slot]=c.equipment[slot]===id?null:id;persist();render();toast(c.equipment[slot]?`${ITEMS[id].name} equipped.`:`${ITEMS[id].name} unequipped.`);return}if(id==='potion'){c.inventory.potion--;const healed=Math.min(c.maxHealth-c.health,38);c.health+=healed;addFeed('🧪','Healing potion used',`You restored ${healed} health.`);persist();render();toast(`Recovered ${healed} health.`);return}if(id==='smoke_bomb'){toast('Smoke Bomb is best saved for a dangerous encounter; use it from the Adventure battle panel.');return}return irV02UseItem(id)}
function irRestInjuries(days){const c=state?.character;if(!c||!Array.isArray(c.injuries))return;c.injuries=c.injuries.map(x=>({...x,days:Math.max(0,(Number(x.days)||0)-days)})).filter(x=>x.days>0)}
dayPass = function(days,activity='Time passes'){const before=state?.character?.daysLived||0;irV02DayPass(days,activity);const after=state?.character?.daysLived||before;irRestInjuries(Math.max(0,after-before))}

// Upgrade save schema without regenerating away in-progress combat or dungeon state.
normalizeSave = function(input){const raw=clone(input);const extras={dungeon:raw.world?.dungeon||null,insideDungeon:!!raw.world?.insideDungeon,combat:raw.combat||null,warning:raw.warning||null,hunt:raw.hunt||null,pathEventHistory:raw.pathEventHistory||[],worldStartRace:raw.world?.startRace,worldStartBackground:raw.world?.startBackground};const s=irV02NormalizeSave(raw);s.version=3;s.world.dungeon=extras.dungeon&&typeof extras.dungeon==='object'?extras.dungeon:null;s.world.insideDungeon=extras.insideDungeon;s.world.startRace=extras.worldStartRace||s.world.startRace||s.character.race;s.world.startBackground=extras.worldStartBackground||s.world.startBackground||s.character.background;s.combat=extras.combat&&typeof extras.combat==='object'?extras.combat:null;s.warning=extras.warning&&typeof extras.warning==='object'?extras.warning:null;s.hunt=extras.hunt&&typeof extras.hunt==='object'?extras.hunt:null;s.pathEventHistory=Array.isArray(extras.pathEventHistory)?extras.pathEventHistory.slice(0,80):[];const c=s.character;c.background=BACKGROUNDS[c.background]?c.background:(IR_DEFAULT_BACKGROUND[c.race]||'village');const prof=BACKGROUNDS[c.background]||BACKGROUNDS.village;c.lifePath=String(c.lifePath||prof.path||'Independent');c.openingStory=String(c.openingStory||prof.opening||'A new life begins.');c.pathProgress=c.pathProgress&&typeof c.pathProgress==='object'?c.pathProgress:{offersTaken:0,contractsCompleted:0,contactReputation:{locals:0,shadow:0,craft:0,arcane:0,wilds:0},flags:[]};c.pathProgress.offersTaken=Math.max(0,Math.floor(Number(c.pathProgress.offersTaken)||0));c.pathProgress.contractsCompleted=Math.max(0,Math.floor(Number(c.pathProgress.contractsCompleted)||0));c.pathProgress.contactReputation=c.pathProgress.contactReputation&&typeof c.pathProgress.contactReputation==='object'?c.pathProgress.contactReputation:{locals:0,shadow:0,craft:0,arcane:0,wilds:0};c.pathProgress.flags=Array.isArray(c.pathProgress.flags)?c.pathProgress.flags.slice(0,80):[];c.combatStats=c.combatStats&&typeof c.combatStats==='object'?c.combatStats:{wins:0,defeats:0,escapes:0,monstersDefeated:0,totalExperience:0};for(const k of ['wins','defeats','escapes','monstersDefeated','totalExperience'])c.combatStats[k]=Math.max(0,Math.floor(Number(c.combatStats[k])||0));c.injuries=Array.isArray(c.injuries)?c.injuries.filter(x=>x&&typeof x==='object'&&Number(x.days)>0).slice(0,20).map(x=>({id:irSafeText(x.id,40),name:irSafeText(x.name,60),days:clamp(Math.floor(Number(x.days)||1),1,60),detail:irSafeText(x.detail||'',200)})):[];c.contacts=Array.isArray(c.contacts)?c.contacts.slice(0,30):[];c.pathHistory=Array.isArray(c.pathHistory)?c.pathHistory.slice(0,50):[];c.huntTrophies=Array.isArray(c.huntTrophies)?c.huntTrophies.slice(0,40):[];const inv=c.inventory||{};c.equipment={weapon:IR_WEAPON_DATA[c.equipment?.weapon]&&inv[c.equipment.weapon]>0?c.equipment.weapon:(inv.dagger?'dagger':null),armor:c.equipment?.armor==='leather_armor'&&inv.leather_armor>0?'leather_armor':null,offhand:c.equipment?.offhand==='shield'&&inv.shield>0?'shield':null};if(s.combat){const e=IR_ENEMIES[s.combat.enemyId];if(!e||!s.combat.active||!Number.isFinite(Number(s.combat.enemyHP))||!Number.isFinite(Number(s.combat.enemyMaxHP))||Number(s.combat.enemyMaxHP)<=0)s.combat=null;else{s.combat.enemyHP=clamp(Number(s.combat.enemyHP),0,Number(s.combat.enemyMaxHP));s.combat.enemyMaxHP=clamp(Number(s.combat.enemyMaxHP),1,999);s.combat.log=Array.isArray(s.combat.log)?s.combat.log.slice(0,9).map(x=>irSafeText(x,350)):[];s.combat.playerStatuses=Array.isArray(s.combat.playerStatuses)?s.combat.playerStatuses.filter(x=>['poison','bleed','curse'].includes(x.id)).slice(0,6):[];s.combat.source=s.combat.source&&typeof s.combat.source==='object'?s.combat.source:{type:'wild'}}}if(s.warning&&!IR_ENEMIES[s.warning.enemyId])s.warning=null;if(s.hunt&&!IR_ENEMIES[s.hunt.enemyId])s.hunt=null;if(s.world.dungeon){const d=s.world.dungeon;if(!['branch','trap','guard','treasure','boss','done','entrance'].includes(d.stage))d.stage='entrance';d.entered=!!d.entered;d.cleared=!!d.cleared;d.history=Array.isArray(d.history)?d.history.slice(0,30):[];if(!s.world.region.sites.some(x=>x.id===d.siteId))s.world.dungeon=null;}return s}
validSave = function(s){return !!(s&&typeof s==='object'&&s.character&&typeof s.character.name==='string'&&s.character.name.trim()&&RACES[s.character.race]&&s.calendar&&s.world&&Array.isArray(s.feed))}
exportSave = function(){try{if(!state?.character)return;const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`infinite-realms-${(state.character.name||'save').toLowerCase().replace(/[^a-z0-9]+/g,'-')}-v03.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),500);toast('Version 0.3 backup exported.')}catch(e){toast('Export failed in this browser.')}}
topbar = function(){return `<header class="topbar"><div class="brand"><div class="brand-mark">✧</div><div><div class="brand-title">INFINITE REALMS</div><div class="brand-sub">VERSION 0.4 · LIFE PATHS & ADVENTURE</div></div></div><div class="top-actions">${state?.character?`<span class="save-status" id="saveStatus"><span class="status-dot"></span> Saved locally</span><button class="button subtle" data-action="save-modal">Save</button><button class="button" data-action="load-modal">Load</button><button class="button subtle" data-action="new-life">New Life</button>`:''}<button class="button subtle" data-action="backup">↧ Backup</button></div></header>`}
shell = function(inner){return `${topbar()}<div class="layout"><aside class="sidebar"><div class="nav-label">YOUR JOURNEY</div><nav class="nav">${navButtons()}</nav><div class="side-card"><div class="side-kicker">THE WORLD</div><strong>${esc(state.world.region.name)}</strong><p>${esc(state.world.region.desc)}</p><div style="margin-top:12px"><span class="tag">SEED ${esc(state.world.seed||'LEGACY')}</span></div></div><div class="side-card"><div class="side-kicker">VERSION 0.4</div><strong>One life. Many paths.</strong><p>Race-shaped careers, seeded exploration, turn-based combat, hunting, and a persistent first dungeon.</p></div><div class="side-footer">AUTOSAVE ENABLED<br>LOCAL SAVE · EXPORT BACKUP ANYTIME</div></aside><main class="main">${state.pendingEvent?pendingEventCard():''}${inner}<div class="footer-note">INFINITE REALMS · VERSION 0.4 · LIFE PATHS, COMBAT AND DUNGEON PROGRESS SAVE WITH YOUR LIFE</div></main></div><nav class="mobile-nav">${navButtons(true)}</nav>${renderModal()}`}
function irBattleAllowedAction(a){return ['battle-move','save-modal','load-modal','save-slot','load-slot','close-modal','backup','import','delete-slot'].includes(a)}
runAction = function(target){const a=target.dataset.action;switch(a){case'seek-opportunity':irSeekOpportunity();return;case'start-hunt':irStartHunt();return;case'hunt-choice':irHuntAction(target.dataset.choice);return;case'discover-dungeon':irDiscoverDungeon();return;case'enter-dungeon':irEnterDungeon();return;case'dungeon-choice':irDungeonChoice(target.dataset.choice);return;case'warning-fight':irBattleStartFromWarning();return;case'warning-avoid':irAvoidWarning();return;case'warning-track':{if(!state.warning)return;const w=state.warning;state.warning=null;state.hunt={enemyId:w.enemyId,quality:Math.max(5,(state.character.skills.Survival?.level||1)*2),siteId:site().id,origin:'warning',startedAt:dateLabel(),prepared:false};persist();render();toast('The threat’s tracks have been marked. You can prepare before pursuing.');return}case'battle-move':irBattleMove(target.dataset.move,target.dataset.item);return;case'new-confirmed':state=null;modal=null;createRace='human';createBackground=IR_DEFAULT_BACKGROUND.human;createName='';createSeed=Math.random().toString(36).slice(2,10).toUpperCase();createStart=BACKGROUNDS[createBackground]?.defaultStart||'settlement';render();return;default:if(state?.combat?.active&&!irBattleAllowedAction(a)){toast('Finish the current encounter before taking other actions. You can still save or back up your life.');return}return irV02RunAction(target)}}
function irInstallV03Handlers(){document.addEventListener('click',e=>{const act=e.target.closest('[data-action]');if(act){e.preventDefault();e.stopImmediatePropagation();runAction(act)}},true);document.addEventListener('click',e=>{const rb=e.target.closest('[data-race]');if(rb){const id=rb.dataset.race;if(IR_DEFAULT_BACKGROUND[id]){createBackground=IR_DEFAULT_BACKGROUND[id];createStart=BACKGROUNDS[createBackground]?.defaultStart||'settlement';render()}return}const bb=e.target.closest('[data-background]');if(bb){const b=BACKGROUNDS[bb.dataset.background];if(b?.defaultStart)createStart=b.defaultStart;render();return}if(e.target.closest('[data-action="new-life"]')){ /* confirmation remains handled by the base game */ }});document.addEventListener('change',e=>{if(e.target?.id==='worldSeed')createSeed=String(e.target.value||'').slice(0,32)});}
boot = function(){let saved=null;try{saved=readAutosave()}catch(e){saved=null}if(saved){state=saved;state.version=3;state.view=['Life','World','Adventure','Inventory','Character'].includes(state.view)?state.view:'Life';}else state=null;if(!state?.character&&(!BACKGROUNDS[createBackground]||createBackground==='village')){createRace='human';createBackground=IR_DEFAULT_BACKGROUND.human;createStart=BACKGROUNDS[createBackground].defaultStart}try{irInstallInputHandlers()}catch(e){}try{irInstallV03Handlers()}catch(e){}render();if(state?.character)persist()}


const irV02RenderModal = renderModal;
renderModal = function(){if(modal?.kind==='jobs'){const jobs=irAvailableJobs();return `<div class="overlay" data-dismiss="modal"><section class="modal" role="dialog" aria-modal="true" aria-label="Work and life path board"><div class="modal-header"><div><div class="eyebrow">WORK & LIFE-PATH BOARD</div><h2>Find work</h2><p>Only opportunities currently open to your race, background, skills, and location are listed.</p></div><button class="close-btn" data-action="close-modal">×</button></div>${jobs.map(j=>`<div class="job-row"><div class="row-icon">${j.icon}</div><div class="row-main"><strong>${esc(j.name)} ${j.pathRace?'<span class="tag purple">SPECIALTY</span>':''}</strong><p>${esc(j.desc)}</p><p>Requirement: ${esc(j.req)}</p></div><div class="row-side"><b>+${j.pay} ◈</b><button class="button small" data-action="apply-job" data-job="${j.id}">Apply</button></div></div>`).join('')||'<div class="empty">No suitable positions here. Travel to a settlement or seek a life-path opportunity.</div>'}<div class="modal-actions"><button class="button subtle" data-action="close-modal">Close board</button></div></section></div>`}return irV02RenderModal()}
// Preserve the original entry requirements for the generic jobs as well as the new path jobs.
const irV03JobReqBase = irJobMeetsRequirements;
irJobMeetsRequirements = function(j,c=state.character){if(!j||!c)return false;if(j.id==='laborer'&&(c.attrs.Strength||0)<9)return false;if(j.id==='courier'&&(c.attrs.Agility||0)<9)return false;if(j.id==='scribe'&&(c.attrs.Intelligence||0)<9)return false;if(j.id==='apprentice'&&(c.skills.Crafting?.level||1)<2)return false;if(j.id==='guide'&&(c.skills.Survival?.level||1)<2)return false;return irV03JobReqBase(j,c)};
// The older normalizer intentionally knew only v0.2 weapon slots; keep any valid v0.3 equipment.
const irV03NormalizeSaveBase = normalizeSave;
normalizeSave = function(input){const raw=clone(input);const rawEquipment=raw.character?.equipment||{};const rawInventory=raw.character?.inventory||{};const s=irV03NormalizeSaveBase(raw);const c=s.character;c.equipment={weapon:IR_WEAPON_DATA[rawEquipment.weapon]&&Number(rawInventory[rawEquipment.weapon])>0?rawEquipment.weapon:(Number(rawInventory.dagger)>0?'dagger':null),armor:rawEquipment.armor==='leather_armor'&&Number(rawInventory.leather_armor)>0?'leather_armor':null,offhand:rawEquipment.offhand==='shield'&&Number(rawInventory.shield)>0?'shield':null};if(s.combat){const b=s.combat;s.combat.enemyHP=clamp(Number(b.enemyHP),0,Number(b.enemyMaxHP));s.combat.round=clamp(Math.floor(Number(b.round)||1),1,10000);s.combat.enemyAttack=clamp(Number(b.enemyAttack)||1,1,80);s.combat.enemyDefense=clamp(Number(b.enemyDefense)||0,0,30);s.combat.enemyXP=clamp(Number(b.enemyXP)||1,1,9999);s.combat.enemyCoins=Array.isArray(b.enemyCoins)?b.enemyCoins.map(x=>clamp(Number(x)||0,0,9999)):[0,5];}s.version=3;return s};
// Fix a defensive edge case: an unknown enemy ID should fall back to a location encounter, not a missing symbol.
const irV03StartCombatBase = startCombat;
startCombat = function(enemyId=null,source={type:'wild'}){if(typeof enemyId==='string'&&!IR_ENEMIES[enemyId])enemyId=null;return irV03StartCombatBase(enemyId,source)};

// Add concise v0.3 styling while reusing the existing UI system.
const irV03Style=document.createElement('style');irV03Style.textContent=`
.ir-background-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.ir-path-preview{margin-top:14px;padding:15px;border:1px solid var(--line);border-radius:12px;background:linear-gradient(135deg,rgba(112,154,117,.12),rgba(175,140,82,.08))}.ir-path-preview h3{margin:6px 0;font-size:15px}.ir-path-preview p,.ir-path-preview small{display:block;color:var(--muted);font-size:11px;line-height:1.7;margin:0}.ir-path-preview small{margin-top:8px;color:var(--dim)}.ir-adventure-hero{margin-bottom:15px}.ir-combat-panel{border-color:rgba(191,103,91,.42);box-shadow:0 10px 30px rgba(0,0,0,.14)}.ir-battle-bars{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:16px 0}.ir-bar-label{display:flex;gap:10px;align-items:center;justify-content:space-between;font-size:11px;margin-bottom:7px}.ir-bar{height:9px;background:var(--panel2);border-radius:99px;overflow:hidden;border:1px solid var(--line)}.ir-bar span{height:100%;display:block;border-radius:99px;transition:width .18s ease}.ir-bar span.enemy{background:#b75e56}.ir-bar span.player{background:#6cae8b}.ir-battle-status{display:flex;gap:7px;flex-wrap:wrap;margin:12px 0}.ir-battle-actions,.ir-battle-consumables,.ir-choice-row{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.ir-battle-actions .button{flex:1 1 135px;min-height:42px}.ir-battle-consumables{align-items:center;border-top:1px solid var(--line);padding-top:12px}.ir-battle-log{border-radius:10px;padding:12px 14px;background:var(--panel2);margin-top:13px}.ir-battle-log p{font-size:11px;line-height:1.65;margin:8px 0;color:var(--muted)}.ir-battle-log p.latest{color:var(--text);font-weight:600}.ir-panel-copy{font-size:11px;color:var(--muted);line-height:1.75}.ir-record-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:14px 0}.ir-record-stats>div{background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:12px 8px;text-align:center}.ir-record-stats b{display:block;font-size:20px}.ir-record-stats span{display:block;color:var(--muted);font-size:10px;margin-top:4px}.ir-equipment-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.ir-equipment-grid>div{padding:12px;background:var(--panel2);border:1px solid var(--line);border-radius:10px}.ir-equipment-grid p{color:var(--muted);font-size:11px;line-height:1.6;margin:7px 0 0}.ir-dungeon-panel{margin-top:15px;border-color:rgba(173,145,91,.35)}.ir-hunt-panel,.ir-warning-panel{margin:0 0 14px}.ir-warning-panel{border-color:rgba(201,122,92,.5)}.ir-dungeon-history{border-top:1px solid var(--line);margin-top:13px;padding-top:11px}.ir-dungeon-history p{font-size:11px;color:var(--muted);margin:6px 0}.ir-opportunity-box{display:flex;gap:12px;align-items:center;justify-content:space-between;margin-top:14px;padding:13px;border-radius:10px;border:1px solid var(--line);background:var(--panel2)}.ir-opportunity-box p{font-size:11px;color:var(--muted);line-height:1.6;margin:5px 0 0}.ir-career-footnote{font-size:10px;color:var(--dim);margin-top:12px}.tag.warning{color:#f2b7a0;border-color:rgba(213,124,96,.42);background:rgba(213,124,96,.09)}
@media(max-width:760px){.ir-background-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.ir-battle-bars{grid-template-columns:1fr}.ir-record-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.ir-equipment-grid{grid-template-columns:1fr}.ir-opportunity-box{align-items:stretch;flex-direction:column}.ir-opportunity-box .button{width:100%}}
`;document.head.appendChild(irV03Style);
